{"path": "mapLimit.js", "content": "async function mapLimit(items, limit, mapper) {
  // Validate limit: must be a positive integer
  if (!Number.isInteger(limit) || limit <= 0 || !Number.isFinite(limit)) {
    throw new RangeError('limit must be a positive integer');
  }

  // Validate mapper: must be a function
  if (typeof mapper !== 'function') {
    throw new TypeError('mapper must be a function');
  }

  const results = [];
  const indices = [];

  for (const item of items) {
    indices.push(item);
  }

  // Create a map from index to promise
  const indexToPromise = new Map();

  // Process items in order, but allow up to `limit` concurrent
  let activeCount = 0;
  const queue = [];

  for (let i = 0; i < items.length; i++) {
    // Wait if we're at the limit
    while (activeCount >= limit && queue.length > 0) {
      queue.shift();
      activeCount--;
    }

    // Start the next item
    const item = items[i];
    const index = i;

    const promise = (async () => {
      activeCount++;
      try {
        const result = await mapper(item, index);
        results.push(result);
        return index;
      } catch (e) {
        throw e;
      } finally {
        activeCount--;
      }
    })();

    indexToPromise.set(index, promise);
    queue.push(index);
  }

  // Wait for all promises to complete
  await Promise.all(Object.values(indexToPromise));

  // Sort results by original index to maintain input order
  const sortedIndices = Array.from(indices).sort((a, b) => a - b);
  const sortedResults = sortedIndices.map(index => results[index]);

  return sortedResults;
}

module.exports = { mapLimit };
"}

